package br.com.onda;
import android.app.Activity;
import android.os.Bundle;
import android.graphics.*;
import android.view.*;
import android.widget.*;
import java.util.*;

public class AppearanceActivity extends Activity {
 private final List<Button> buttons=new ArrayList<>();private final List<View> cards=new ArrayList<>();private TextView selected;
 @Override public void onCreate(Bundle state){super.onCreate(state);LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);Ui.background(root);root.setOnApplyWindowInsetsListener((v,i)->{root.setPadding(Ui.dp(this,16),Ui.dp(this,12)+i.getSystemWindowInsetTop(),Ui.dp(this,16),Ui.dp(this,12)+i.getSystemWindowInsetBottom());return i;});setContentView(root);LinearLayout header=new LinearLayout(this);header.setGravity(Gravity.CENTER_VERTICAL);header.addView(Ui.button(this,"‹",v->finish()),new LinearLayout.LayoutParams(Ui.dp(this,48),Ui.dp(this,48)));header.addView(Ui.text(this,"Aparências do Onda",21,Ui.TEXT),new LinearLayout.LayoutParams(0,-2,1));root.addView(header);selected=Ui.text(this,"",14,Ui.CYAN);selected.setPadding(0,Ui.dp(this,12),0,Ui.dp(this,12));root.addView(selected);ScrollView scroll=new ScrollView(this);scroll.setContentDescription("Lista de aparências");LinearLayout content=new LinearLayout(this);content.setOrientation(LinearLayout.VERTICAL);scroll.addView(content);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));for(AppearancePalette p:AppearancePalette.ALL){LinearLayout card=new LinearLayout(this);card.setOrientation(LinearLayout.VERTICAL);card.setPadding(Ui.dp(this,14),Ui.dp(this,14),Ui.dp(this,14),Ui.dp(this,12));LinearLayout.LayoutParams margin=new LinearLayout.LayoutParams(-1,-2);margin.bottomMargin=Ui.dp(this,12);content.addView(card,margin);cards.add(card);TextView title=Ui.text(this,p.name,19,Ui.TEXT);Ui.bold(title);card.addView(title);TextView detail=Ui.text(this,p.description,13,Ui.MUTED);detail.setPadding(0,Ui.dp(this,6),0,Ui.dp(this,10));card.addView(detail);card.addView(new Preview(this,p),new LinearLayout.LayoutParams(-1,Ui.dp(this,116)));Button use=Ui.button(this,"Usar "+p.name,v->{AppearanceStyles.choose(this,p);updateSelection();});use.setContentDescription("Usar aparência "+p.name);card.addView(use,new LinearLayout.LayoutParams(-1,-2));buttons.add(use);}content.addView(Ui.text(this,"A escolha fica salva neste celular e muda cores, gradientes e cantos dos cartões. Mantém os controles, o tamanho de fonte do Android e a reprodução. Prévias estáticas, sem animações contínuas.",12,Ui.MUTED));updateSelection();}
 private void updateSelection(){selected.setText("Aparência atual: "+Ui.palette.name);for(int i=0;i<buttons.size();i++){boolean active=AppearancePalette.ALL[i]==Ui.palette;Button b=buttons.get(i);b.setText(active?"Em uso":"Usar "+AppearancePalette.ALL[i].name);b.setEnabled(!active);Ui.chip(b,active);Ui.card(cards.get(i),active);}}
 private static final class Preview extends View {
  private final AppearancePalette palette;private final Paint p=new Paint(Paint.ANTI_ALIAS_FLAG);
  Preview(android.content.Context c,AppearancePalette palette){super(c);this.palette=palette;setImportantForAccessibility(View.IMPORTANT_FOR_ACCESSIBILITY_NO);}
  @Override protected void onDraw(Canvas canvas){float scale=getHeight()/116f,w=getWidth()/scale;canvas.save();canvas.scale(scale,scale);p.setShader(new LinearGradient(0,0,w,116,palette.bg,palette.end,Shader.TileMode.CLAMP));canvas.drawRoundRect(0,0,w,116,12*palette.corners,12*palette.corners,p);p.setShader(null);p.setColor(palette.accent);p.setTypeface(Typeface.create("sans-serif-medium",Typeface.NORMAL));p.setTextSize(15);canvas.drawText("onda",12,23,p);p.setColor(AppearancePalette.MUTED);p.setTextSize(8);canvas.drawText("MINHA TRILHA",12,38,p);float middle=w*.6f;p.setColor(palette.surface);canvas.drawRoundRect(10,46,middle-6,78,8*palette.corners,8*palette.corners,p);canvas.drawRoundRect(10,84,middle-6,106,8*palette.corners,8*palette.corners,p);p.setColor(palette.accent);canvas.drawRoundRect(17,54,29,69,3,3,p);p.setColor(AppearancePalette.TEXT);p.setTextSize(9);canvas.drawText("Minha música",36,61,p);p.setColor(AppearancePalette.MUTED);p.setTextSize(7);canvas.drawText("Artista favorito",36,71,p);p.setColor(palette.secondary);canvas.drawRoundRect(17,91,middle-18,97,3,3,p);p.setColor(palette.raised);canvas.drawRoundRect(middle,12,w-10,106,12*palette.corners,12*palette.corners,p);p.setColor(palette.accent);for(int i=0;i<5;i++){float x=middle+12+i*(w-middle-38)/5f,h=new float[]{14,25,39,23,12}[i];canvas.drawRoundRect(x,44-h/2,x+4,44+h/2,2,2,p);}p.setColor(palette.secondary);canvas.drawRect(middle+12,72,w-22,74,p);p.setColor(palette.accent);canvas.drawCircle((middle+w-10)/2,91,8,p);canvas.restore();}
 }
}
